const raw = $json;
const fail = () => { throw new Error('CONTRACT_INVALID'); };
const rootKeys = ['as_of','categories','dispatch','generated_at','range','report_type','schema_version','secure_path','timezone','total'];
if (!raw || typeof raw !== 'object' || Array.isArray(raw) || JSON.stringify(Object.keys(raw).sort()) !== JSON.stringify(rootKeys.slice().sort())) fail();
const datePattern = /^\d{4}-\d{2}-\d{2}$/;
const realDate = (value) => { if (typeof value !== 'string' || !datePattern.test(value)) return false; const parsed = new Date(value + 'T00:00:00Z'); return !Number.isNaN(parsed.getTime()) && parsed.toISOString().slice(0, 10) === value; };
if (raw.schema_version !== 1 || raw.timezone !== 'America/Guatemala' || raw.report_type !== 'weekly_data_quality_watchdog' || raw.secure_path !== '/dashboard') fail();
if (typeof raw.generated_at !== 'string' || Number.isNaN(Date.parse(raw.generated_at))) fail();
if (!raw.range || Object.keys(raw.range).sort().join(',') !== 'from,to' || !realDate(raw.range.from) || !realDate(raw.range.to) || !realDate(raw.as_of)) fail();
const from = Date.parse(raw.range.from + 'T00:00:00Z');
const to = Date.parse(raw.range.to + 'T00:00:00Z');
if (to - from !== 6 * 86400000 || new Date(from).getUTCDay() !== 1 || new Date(to).getUTCDay() !== 0 || Date.parse(raw.as_of + 'T00:00:00Z') !== to + 86400000) fail();
if (!Number.isSafeInteger(raw.total) || raw.total < 0 || raw.total > 1000000 || !Array.isArray(raw.categories)) fail();
if (!raw.dispatch || typeof raw.dispatch !== 'object' || Array.isArray(raw.dispatch)) fail();
const status = raw.dispatch.status;
if (!['ready','no_results','already_processed'].includes(status)) fail();
const categoryCatalog = new Map([['patient_required_identity_missing',['Identificacion obligatoria de paciente incompleta','Hay registros con campos obligatorios de identificacion vacios.']],['pregnancy_link_missing',['Registros prenatales sin embarazo asociado','Hay registros que requieren embarazo y no tienen una relacion asociada.']],['pregnancy_patient_mismatch',['Relaciones paciente-embarazo inconsistentes','Hay registros cuyo paciente no coincide con el embarazo relacionado.']],['concurrent_open_pregnancies',['Estados de embarazo incompatibles','Hay pacientes con mas de un embarazo activo o en puerperio.']],['future_prenatal_control',['Controles prenatales con fecha futura','Hay controles con una fecha posterior al dia operativo actual.']],['scheduled_appointment_closed_pregnancy',['Citas programadas en embarazos cerrados','Hay citas aun programadas dentro de embarazos cerrados.']]]);
const cleanCategories = [];
const seen = new Set();
let sum = 0;
for (const category of raw.categories) {
  if (!category || typeof category !== 'object' || Array.isArray(category) || Object.keys(category).sort().join(',') !== 'code,count,description,label') fail();
  if (typeof category.code !== 'string' || !/^[a-z][a-z0-9_]{2,79}$/.test(category.code) || seen.has(category.code)) fail();
  if (typeof category.label !== 'string' || category.label.length < 3 || category.label.length > 120 || /[\u0000-\u001f\u007f]/.test(category.label)) fail();
  if (typeof category.description !== 'string' || category.description.length < 3 || category.description.length > 240 || /[\u0000-\u001f\u007f]/.test(category.description)) fail();
  const expected = categoryCatalog.get(category.code); if (!expected || category.label !== expected[0] || category.description !== expected[1]) fail();
  if (!Number.isSafeInteger(category.count) || category.count < 1 || category.count > 1000000) fail();
  seen.add(category.code); sum += category.count; cleanCategories.push({ code: category.code, label: category.label, description: category.description, count: category.count });
}
if (sum !== raw.total) fail();
if (status === 'ready') {
  if (Object.keys(raw.dispatch).sort().join(',') !== 'status,token' || typeof raw.dispatch.token !== 'string' || !/^[A-Za-z0-9_-]{43}$/.test(raw.dispatch.token) || raw.total < 1 || cleanCategories.length < 1) fail();
} else if (Object.keys(raw.dispatch).join(',') !== 'status' || raw.total !== 0 || cleanCategories.length !== 0) fail();
return [{ json: { should_send: status === 'ready', dispatch_token: status === 'ready' ? raw.dispatch.token : null, range: { from: raw.range.from, to: raw.range.to }, as_of: raw.as_of, total: raw.total, categories: cleanCategories } }];

const raw = $json;
if (!raw.should_send || typeof raw.dispatch_token !== 'string' || !Number.isSafeInteger(raw.total) || raw.total < 1 || !Array.isArray(raw.categories) || raw.categories.length < 1) throw new Error('CONTRACT_INVALID');
const escapeHtml = (value) => String(value).replace(/[&<>\"']/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);
const formatDate = (value) => value.split('-').reverse().join('-');
const rows = raw.categories.map((category) => '<tr><td style="padding:8px;border-bottom:1px solid #d1d5db">' + escapeHtml(category.label) + '</td><td style="padding:8px;border-bottom:1px solid #d1d5db;text-align:center">' + category.count + '</td><td style="padding:8px;border-bottom:1px solid #d1d5db">' + escapeHtml(category.description) + '</td></tr>').join('');
const fromLabel = formatDate(raw.range.from);
const toLabel = formatDate(raw.range.to);
const subject = 'CAP Prenatal | Revisión semanal de calidad de datos';
const html = '<div style="font-family:Arial,sans-serif;color:#1f2937;line-height:1.6"><h2 style="color:#155e8e;margin-bottom:8px">Revisión semanal de calidad de datos</h2><p>Buen día.</p><p>CAP Prenatal identificó inconsistencias administrativas que requieren revisión por personal autorizado.</p><p><strong>Período:</strong> ' + fromLabel + ' al ' + toLabel + '<br><strong>Total de incidencias:</strong> ' + raw.total + '</p><table style="border-collapse:collapse;width:100%;max-width:860px"><thead><tr style="background:#155e8e;color:#fff"><th style="padding:8px;text-align:left">Categoría</th><th style="padding:8px;text-align:center">Cantidad</th><th style="padding:8px;text-align:left">Descripción operativa</th></tr></thead><tbody>' + rows + '</tbody></table><p>Ingrese a CAP Prenatal con un usuario autorizado para realizar la revisión correspondiente.</p><p style="font-size:12px;color:#6b7280">Este resumen no contiene datos de pacientes ni información clínica. Mensaje automático; no responda a este correo.</p></div>';
return [{ json: { subject, html, dispatch_token: raw.dispatch_token } }];
